{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']

    # Build node map and children lists
    node_map = {}
    children_map = {}
    for node in nodes:
        nid = node['id']
        node_map[nid] = node
        children_map[nid] = []
    for node in nodes:
        pid = node['parent']
        if pid is not None:
            children_map[pid].append(node['id'])

    # Count symbols
    symbol_count = {}
    for node in nodes:
        sym = node['symbol']
        symbol_count[sym] = symbol_count.get(sym, 0) + 1

    # Initial retained set
    retained = set(node_map.keys())

    # Sort candidates: removable nodes (not root) by depth descending, then id ascending
    candidates = []
    for nid, node in node_map.items():
        if node['removable'] and node['parent'] is not None:  # not root
            candidates.append((node['depth'], nid, node['symbol']))
    candidates.sort(key=lambda x: (-x[0], x[1]))  # depth desc, id asc

    removed_order = []
    for depth, nid, sym in candidates:
        if nid not in retained:
            continue
        node = node_map[nid]
        # Check if any children are still retained
        has_retained_child = any(child in retained for child in children_map[nid])
        if has_retained_child:
            continue
        # Check if removing this node would cause a required symbol to disappear
        can_remove = True
        for req_sym in required_symbols:
            if sym == req_sym and symbol_count.get(req_sym, 0) == 1:
                can_remove = False
                break
        if not can_remove:
            continue
        # Perform removal
        retained.remove(nid)
        symbol_count[sym] -= 1
        removed_order.append(nid)

    # Retained IDs sorted
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }"}
